# LAMMPS input script for elastic constants calculation

# Initialization
units metal
atom_style atomic
boundary p p p

# Read structure
read_data Mg.data

# Define potential
pair_style eam/alloy
pair_coeff * * /potentials/EAM/Mg_Zhou04.eam.alloy Mg

# Energy minimization
minimize 1.0e-10 1.0e-10 100000 100000

# Setup for elastic constant calculation
include /root/lammps/examples/ELASTIC/in.elastic

# Output elastic constants
variable C11 equal ${c11}
variable C12 equal ${c12}
variable C13 equal ${c13}
variable C14 equal ${c14}
variable C15 equal ${c15}
variable C16 equal ${c16}
variable C22 equal ${c22}
variable C23 equal ${c23}
variable C24 equal ${c24}
variable C25 equal ${c25}
variable C26 equal ${c26}
variable C33 equal ${c33}
variable C34 equal ${c34}
variable C35 equal ${c35}
variable C36 equal ${c36}
variable C44 equal ${c44}
variable C45 equal ${c45}
variable C46 equal ${c46}
variable C55 equal ${c55}
variable C56 equal ${c56}
variable C66 equal ${c66}

# Calculate bulk modulus (Voigt average)
variable B equal (${c11}+${c22}+${c33}+2*(${c12}+${c13}+${c23}))/9

print "Bulk modulus = ${B} GPa"
